+			}}
+		}
+		return pvc
+	}
+	managedNamespace := labNamespaceObject("lab1", "c9s-lab1")
+
+	for _, tt := range []struct {
+		name          string
+		cleanup       bool
+		claims        []k8sruntime.Object
+		wantClaims    []string
