func checkLabRuntimeCommandSupport(cobraCmd *cobra.Command, runtimeName string) error {
	if !clablabruntime.IsLabRuntimeName(runtimeName) {
		return nil
	}

	for cmd := cobraCmd; cmd != nil; cmd = cmd.Parent() {
		if _, ok := labRuntimeUnsupportedCommands[cmd.Name()]; ok {
			return fmt.Errorf("the %q command is not supported with lab runtime %q",
				cmd.Name(), runtimeName)
		}
	}

	if getCommandPath(cobraCmd) == "graph" && !graphRendersFromTopologyFile(cobraCmd) {
		return fmt.Errorf(
			"the %q command needs running containers with lab runtime %q unless it renders "+
				"from the topology file alone; use --offline, --dot, --mermaid or --drawio",
			"graph", runtimeName)
	}

	if getCommandPath(cobraCmd) == "inspect.interfaces" {
		return fmt.Errorf("the %q command is not supported with lab runtime %q",
			"inspect interfaces", runtimeName)
	}

	var unsupported []string
	for _, flagName := range labRuntimeUnsupportedFlags[getCommandPath(cobraCmd)] {
		if labRuntimeFlagWasSet(cobraCmd, flagName) {
			unsupported = append(unsupported, "--"+flagName)
		}
	}
	if len(unsupported) != 0 {
		sort.Strings(unsupported)

		return fmt.Errorf(
			"flag(s) %s are not supported with the %q command and lab runtime %q",
			strings.Join(unsupported, ", "),
			cobraCmd.Name(),
			runtimeName,
		)
	}

	return nil
}

func graphRendersFromTopologyFile(cobraCmd *cobra.Command) bool {
	for _, flagName := range graphTopologyFileFlags {
		flag := cobraCmd.Flag(flagName)
		if flag != nil && flag.Value.String() == "true" &&
			labRuntimeFlagWasSet(cobraCmd, flagName) {
			return true
		}
	}

	return false
}

func labRuntimeFlagWasSet(cobraCmd *cobra.Command, flagName string) bool {
	flag := cobraCmd.Flag(flagName)
	if flag == nil {
		return false
	}

	if flag.Changed {
		return true
	}

	if v == nil {
		return false
	}

	commandKey := getCommandPath(cobraCmd) + "." + flagName
	if v.IsSet(commandKey) {
		return true
	}

	return v.IsSet(flagName)
}

// getTopoFilePath finds *.clab.y*ml file in the current working directory
// if the file was not specified.
// If the topology file refers to a git repository, it will be cloned to the current directory.
// Errors if more than one file is found by the glob path.
func getTopoFilePath(cobraCmd *cobra.Command, o *Options) error { // skipcq: GO-R1005
	// set commands which may use topo file find functionality, the rest don't need it
	if cobraCmd.Name() != "deploy" &&
		cobraCmd.Name() != "destroy" &&
		cobraCmd.Name() != "start" &&
		cobraCmd.Name() != "stop" &&
		cobraCmd.Name() != "restart" &&
		cobraCmd.Name() != "redeploy" &&
		cobraCmd.Name() != "inspect" &&
		cobraCmd.Name() != "save" &&
		cobraCmd.Name() != "graph" &&
		cobraCmd.Name() != "validate" &&
		cobraCmd.Name() != "interfaces" {
		return nil
	}

	// start/stop/restart topology lookup applies only to top-level lifecycle commands.
	// nested commands like tools api-server start|stop are excluded.
	if (cobraCmd.Name() == "start" || cobraCmd.Name() == "stop" || cobraCmd.Name() == "restart") &&
		(cobraCmd.Parent() == nil || cobraCmd.Parent().Name() != "containerlab") {
		return nil
	}

	// inspect and destroy commands with --all flag don't use file find functionality
	if (cobraCmd.Name() == "inspect" || cobraCmd.Name() == "destroy") &&
		cobraCmd.Flag("all") != nil &&
		cobraCmd.Flag("all").Value.String() == "true" {
		return nil
	}

