func (c *CLab) saveWithLabRuntime(ctx context.Context, opts *SaveOptions) error {
	if opts.copyDst != "" {
		resolvedDst, err := c.resolveCopyOutDst(opts.copyDst)
		if err != nil {
			return err
		}
		opts.copyDst = resolvedDst
	}

	result, err := c.LabRuntime.Save(ctx, clablabruntime.SaveRequest{
		Name:  c.Config.Name,
		Nodes: c.nodeFilter,
		Copy:  opts.copyDst != "",
	})
	if err != nil {
		return err
	}

	if opts.copyDst == "" || result == nil {
		return nil
	}

	return c.copyLabRuntimeSavedFiles(result, opts.copyDst)
}

func (c *CLab) containersFromLabState(
	state *clablabruntime.LabState,
) []clabruntime.GenericContainer {
	if state == nil {
		return nil
	}

	nodes := state.Nodes
	if len(nodes) == 0 && c.Config.Topology != nil {
		nodeNames := make([]string, 0, len(c.Config.Topology.Nodes))
		for nodeName := range c.Config.Topology.Nodes {
			nodeNames = append(nodeNames, nodeName)
		}
		sort.Strings(nodeNames)

		nodes = make([]clablabruntime.NodeState, 0, len(nodeNames))
		for _, nodeName := range nodeNames {
			nodes = append(nodes, clablabruntime.NodeState{
				Name:  nodeName,
				Kind:  c.Config.Topology.GetNodeKind(nodeName),
				Image: c.Config.Topology.GetNodeImage(nodeName),
				State: state.State,
				Ready: state.Ready,
			})
		}
	}

	containers := make([]clabruntime.GenericContainer, 0, len(nodes))
	for _, node := range nodes {
		containers = append(containers, c.containerFromLabNode(state, node))
	}

	return containers
}

func (c *CLab) containerFromLabNode(
	state *clablabruntime.LabState,
	node clablabruntime.NodeState,
) clabruntime.GenericContainer {
	nodeName := fmt.Sprintf("%s-%s", state.Name, node.Name)
	containerState := node.State
	containerStatus := node.State
	if containerState == "" {
		containerState = state.State
	}
	if node.Ready {
		containerState = "running"
		containerStatus = "healthy"
	}

	labels := map[string]string{
		clabconstants.Containerlab: state.Name,
		clabconstants.NodeName:     node.Name,
		clabconstants.LongName:     nodeName,
		clabconstants.TopoFile:     labRuntimeTopologyPath(c, state),
	}

	var image string
	if c.Config.Topology != nil {
		topologyNode := c.topologyNodeName(node.Name)
		labels[clabconstants.NodeKind] = c.Config.Topology.GetNodeKind(topologyNode)
		image = c.Config.Topology.GetNodeImage(topologyNode)

		if group := c.Config.Topology.GetNodeGroup(topologyNode); group != "" {
			labels[clabconstants.NodeGroup] = group
		}
	}
	if node.Kind != "" {
		labels[clabconstants.NodeKind] = node.Kind
	}
	if node.Image != "" {
		image = node.Image
	}

	if state.Owner != "" {
		labels[clabconstants.Owner] = state.Owner
	} else if c.customOwner != "" {
		labels[clabconstants.Owner] = c.customOwner
	}

	// The ID names the node uniquely across namespaces and labs. It is also the short ID, so
	// inspect reports it as container_id and it matches the events actor ID.
	id := labRuntimeContainerID(state.Namespace, state.Name, node.Name)

	return clabruntime.GenericContainer{
		Names:           []string{nodeName},
		ID:              id,
		ShortID:         id,
		Image:           image,
		State:           containerState,
		Status:          containerStatus,
		Labels:          labels,
		NetworkName:     state.Namespace,
		NetworkSettings: managementAddress(node),
		Workload: &clabtypes.LabRuntimeWorkload{
			Namespace:           state.Namespace,
			Pod:                 node.Pod,
			Container:           node.Container,
			NodeUID:             node.NodeUID,
			ExposedPorts:        node.ExposedPorts,
			LoadBalancerAddress: node.LoadBalancerAddress,
		},
	}
}

// labRuntimeContainerID is the ID of a lab runtime node: <namespace>/<lab>/<node>.
func labRuntimeContainerID(namespace, lab, node string) string {
	return fmt.Sprintf("%s/%s/%s", namespace, lab, node)
}

// topologyNodeName maps a node name a lab runtime reports back onto the topology node it belongs
// to. The runtime renames the nodes Kubernetes cannot carry, so the state it reports does not
// always use the name the topology file wrote.
func (c *CLab) topologyNodeName(name string) string {
	if c.Config.Topology == nil {
		return name
	}
	if _, ok := c.Config.Topology.Nodes[name]; ok {
		return name
	}

	for nodeName := range c.Config.Topology.Nodes {
		if clabnames.SanitizeName(nodeName) == name {
			return nodeName
		}
	}

	return name
}

// managementAddress reports the address a user reaches the node at: the LoadBalancer address
// when the node is exposed, otherwise the allocated management address.
func managementAddress(node clablabruntime.NodeState) clabruntime.GenericMgmtIPs {
	settings := clabruntime.GenericMgmtIPs{}

	if ip := net.ParseIP(node.LoadBalancerAddress); ip != nil {
		if ip.To4() != nil {
			settings.IPv4addr = node.LoadBalancerAddress
			settings.IPv4pLen = 32
		} else {
			settings.IPv6addr = node.LoadBalancerAddress
			settings.IPv6pLen = 128
		}
	}

	if settings.IPv4addr == "" {
		settings.IPv4addr, settings.IPv4pLen = splitManagementCIDR(node.MgmtIPv4Address)
	}
	if settings.IPv6addr == "" {
		settings.IPv6addr, settings.IPv6pLen = splitManagementCIDR(node.MgmtIPv6Address)
	}

	return settings
}

func splitManagementCIDR(cidr string) (string, int) {
	if cidr == "" {
		return "", 0
	}

	ip, network, err := net.ParseCIDR(cidr)
	if err != nil {
		if net.ParseIP(cidr) != nil {
			return cidr, 0
		}

		return "", 0
	}

	prefixLen, _ := network.Mask.Size()

	return ip.String(), prefixLen
}

func labRuntimeTopologyPath(c *CLab, state *clablabruntime.LabState) string {
	if c.TopoPaths.TopologyFileIsSet() {
		return c.TopoPaths.TopologyFilenameAbsPath()
	}

	if state.TopologyPath != "" {
		return state.TopologyPath
	}

	return fmt.Sprintf("k8s://%s/topologies/%s", state.Namespace, state.Name)
}

func labRuntimeContainerParts(c clabruntime.GenericContainer) (string, string, string, error) {
	parts := strings.Split(c.ID, "/")
	if len(parts) != 3 {
		return "", "", "", fmt.Errorf("expected namespace/lab/node id, got %q", c.ID)
	}

	return parts[0], parts[1], parts[2], nil
}

func filterLabRuntimeContainers(
	containers []clabruntime.GenericContainer,
	filters []*clabtypes.GenericFilter,
) []clabruntime.GenericContainer {
	if len(filters) == 0 {
		return containers
	}

	filtered := make([]clabruntime.GenericContainer, 0, len(containers))
	for _, container := range containers {
		if labRuntimeContainerMatches(container, filters) {
			filtered = append(filtered, container)
		}
	}

	return filtered
}

func labRuntimeContainerMatches(
	container clabruntime.GenericContainer,
	filters []*clabtypes.GenericFilter,
) bool {
	for _, filter := range filters {
		switch filter.FilterType {
		case "name":
			if !labRuntimeNameMatches(container.Names, filter.Match) {
				return false
			}
		case "id":
			if container.ID != filter.Match && !strings.HasPrefix(container.ID, filter.Match) {
				return false
			}
		case "label":
			if !labRuntimeLabelMatches(container.Labels, filter) {
				return false
			}
		}
	}

	return true
}

func labRuntimeNameMatches(names []string, match string) bool {
	for _, name := range names {
		if name == match || strings.Contains(name, match) {
			return true
		}
	}

	return false
}

func labRuntimeLabelMatches(labels map[string]string, filter *clabtypes.GenericFilter) bool {
	value, ok := labels[filter.Field]

	switch filter.Operator {
	case "exists":
		return ok
	case "!=":
		return !ok || value != filter.Match
	default:
		return ok && value == filter.Match
	}
}

func (c *CLab) copyLabRuntimeSavedFiles(
	result *clablabruntime.SaveResult,
	dstRoot string,
) error {
	for _, file := range result.Files {
		if file.NodeName == "" || file.Name == "" {
			continue
		}

		relPath, ok := cleanLabRuntimeSavedPath(file.Name)
		if !ok {
			return fmt.Errorf("refusing to copy unsafe saved config path %q", file.Name)
		}

		nodeDstDir := filepath.Join(dstRoot, file.NodeName)
		dstPath := filepath.Join(nodeDstDir, relPath)
		if err := os.MkdirAll(
			filepath.Dir(dstPath),
			clabconstants.PermissionsDirDefault,
		); err != nil {
			return fmt.Errorf("failed to create save dst directory %q: %w",
				filepath.Dir(dstPath), err)
		}

		if file.LinkTarget != "" {
			linkTarget, ok := cleanLabRuntimeSavedLinkTarget(file.LinkTarget)
			if !ok {
				return fmt.Errorf("refusing to create unsafe saved config symlink %q -> %q",
					file.Name, file.LinkTarget)
			}

			_ = os.Remove(dstPath)
			if err := os.Symlink(linkTarget, dstPath); err != nil {
				return fmt.Errorf("failed to create symlink %q -> %q: %w",
					dstPath, linkTarget, err)
			}

			continue
		}

		mode := os.FileMode(file.Mode)
		if mode == 0 {
			mode = clabconstants.PermissionsFileDefault
		}

		if err := os.WriteFile(dstPath, file.Data, mode); err != nil {
			return fmt.Errorf("failed to write saved config %q: %w", dstPath, err)
		}

		log.Info(
			"copied saved config",
			"node", file.NodeName,
			"dst", dstPath,
		)
	}

	return nil
}

func cleanLabRuntimeSavedPath(name string) (string, bool) {
	cleaned := filepath.Clean(name)
	if cleaned == "." || filepath.IsAbs(cleaned) ||
		strings.HasPrefix(cleaned, ".."+string(filepath.Separator)) ||
		cleaned == ".." {
		return "", false
	}

	return cleaned, true
}

func cleanLabRuntimeSavedLinkTarget(target string) (string, bool) {
	cleaned := filepath.Clean(target)
	if filepath.IsAbs(cleaned) ||
		strings.HasPrefix(cleaned, ".."+string(filepath.Separator)) ||
		cleaned == ".." {
		return "", false
	}

	return cleaned, true
}

package events

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/charmbracelet/log"
	clabconstants "github.com/srl-labs/containerlab/constants"
	clabcore "github.com/srl-labs/containerlab/core"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
	clabruntime "github.com/srl-labs/containerlab/runtime"
	clabtypes "github.com/srl-labs/containerlab/types"
	clabutils "github.com/srl-labs/containerlab/utils"
)

// Stream subscribes to the selected runtime and netlink sources and forwards
// aggregated events to the configured writer.
func Stream(ctx context.Context, opts Options) error {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()

	clab, err := clabcore.NewContainerLab(opts.ClabOptions...)
	if err != nil {
		return err
	}

	if clab.LabRuntime != nil {
		return streamLabRuntimeEvents(ctx, clab, opts)
	}

	runtime, ok := clab.Runtimes[opts.Runtime]
	if !ok {
		return fmt.Errorf("runtime %q is not initialized", opts.Runtime)
	}

	printer, err := newFormatter(opts.Format, opts.writer())
	if err != nil {
		return err
	}

	eventCh := make(chan aggregatedEvent, 128)
	registry := newNetlinkRegistry(
		ctx,
		eventCh,
		opts.IncludeInitialState,
		opts.IncludeInterfaceStats,
		opts.StatsInterval,
	)

	containers, err := clab.ListContainers(ctx, clabcore.WithListclabLabelExists())
	if err != nil {
		return fmt.Errorf("failed to list containers: %w", err)
	}

	if opts.IncludeInitialState {
		go emitContainerSnapshots(ctx, containers, eventCh)
	}

	for idx := range containers {
		container := containers[idx]
		if !isRunningContainer(&container) {
			continue
		}

		registry.Start(&container)
	}

	streamOpts := clabruntime.EventStreamOptions{
		Labels: map[string]string{
			clabconstants.Containerlab: "",
		},
	}

	runtimeEvents, runtimeErrs, err := runtime.StreamEvents(ctx, streamOpts)
	if err != nil {
		return fmt.Errorf("failed to stream events for runtime %q: %w", opts.Runtime, err)
	}

	errCh := make(chan error, 1)
	go forwardRuntimeEvents(ctx, runtime, registry, runtimeEvents, runtimeErrs, eventCh, errCh)

	runtimeErrors := errCh

	for {
		select {
		case ev := <-eventCh:
			if err := printer(ev); err != nil {
				log.Debugf("failed to write event: %v", err)
			}
		case err, ok := <-runtimeErrors:
			if !ok {
				runtimeErrors = nil

				continue
			}

			if err != nil && !errors.Is(err, context.Canceled) {
				return err
			}
		case <-ctx.Done():
			return nil
		}
	}
}

func streamLabRuntimeEvents(ctx context.Context, clab *clabcore.CLab, opts Options) error {
	printer, err := newFormatter(opts.Format, opts.writer())
	if err != nil {
		return err
	}

	runtimeEvents, runtimeErrs, err := clab.LabRuntime.StreamEvents(
		ctx,
		labRuntimeEventStreamRequest(clab.Config.Name, opts),
	)
	if err != nil {
		return fmt.Errorf("failed to stream events for lab runtime %q: %w", opts.Runtime, err)
	}

	for runtimeEvents != nil || runtimeErrs != nil {
		select {
		case ev, ok := <-runtimeEvents:
			if !ok {
				runtimeEvents = nil

				continue
			}

			if err := printer(aggregatedEventFromLabRuntimeEvent(ev)); err != nil {
				log.Debugf("failed to write event: %v", err)
			}
		case err, ok := <-runtimeErrs:
			if !ok {
				runtimeErrs = nil

				continue
			}

			if err != nil && !errors.Is(err, context.Canceled) {
				return err
			}
		case <-ctx.Done():
			return nil
		}
	}

	return nil
}

// labRuntimeEventStreamRequest scopes a lab runtime event stream. A selected lab (--topo or
// --name) limits the stream to that lab in its namespace. Without one the stream covers every
// namespace, unless a namespace override (--namespace, CLAB_KUBE_NAMESPACE) limits it to that
// namespace; the runtime applies the override.
func labRuntimeEventStreamRequest(labName string, opts Options) clablabruntime.EventStreamRequest {
	return clablabruntime.EventStreamRequest{
		Name:                  labName,
		AllNamespaces:         labName == "",
		IncludeInitialState:   opts.IncludeInitialState,
		IncludeInterfaceStats: opts.IncludeInterfaceStats,
		StatsInterval:         opts.StatsInterval,
	}
}

func aggregatedEventFromLabRuntimeEvent(ev clablabruntime.Event) aggregatedEvent {
	ts := ev.Timestamp
	if ts.IsZero() {
		ts = time.Now()
	}

	return aggregatedEvent{
		Timestamp:   ts,
		Type:        ev.Type,
		Action:      ev.Action,
		ActorID:     ev.ActorID,
		ActorName:   ev.ActorName,
		ActorFullID: ev.ActorFullID,
		Attributes:  cloneStringMap(ev.Attributes),
	}
}

func forwardRuntimeEvents(
	ctx context.Context,
	runtime clabruntime.ContainerRuntime,
	registry *netlinkRegistry,
	runtimeEvents <-chan clabruntime.ContainerEvent,
	runtimeErrs <-chan error,
	eventSink chan<- aggregatedEvent,
	errSink chan<- error,
) {
	defer close(errSink)

	sendErr := func(err error) {
		select {
		case errSink <- err:
		case <-ctx.Done():
		}
	}

	for {
		select {
		case <-ctx.Done():
			return
		case err, ok := <-runtimeErrs:
			if !ok {
				return
			}

			if err != nil && !errors.Is(err, context.Canceled) {
				sendErr(err)

				return
			}
		case ev, ok := <-runtimeEvents:
			if !ok {
				return
			}

			registry.HandleContainerEvent(runtime, ev)

			aggregated := aggregatedEventFromContainerEvent(ctx, runtime, ev)
			select {
			case eventSink <- aggregated:
			case <-ctx.Done():
				return
			}
		}
	}
}

func aggregatedEventFromContainerEvent(
	ctx context.Context,
	runtime clabruntime.ContainerRuntime,
	ev clabruntime.ContainerEvent,
) aggregatedEvent {
	ts := ev.Timestamp
	if ts.IsZero() {
		ts = time.Now()
	}

	attributes := cloneStringMap(ev.Attributes)

	actorFullID := ev.ActorFullID
	if actorFullID == "" {
		actorFullID = ev.ActorID
	}

	actorName := ev.ActorName
	if actorName == "" && attributes != nil {
		actorName = attributes["name"]
	}

	attributes = ensureContainerAttributes(ctx, runtime, attributes, actorFullID, actorName)

	short := ev.ActorID
	if short == "" {
		short = actorFullID
	}

	action := strings.ToLower(ev.Action)
	if action == "" {
		action = ev.Action
	}

	eventType := strings.ToLower(ev.Type)
	if eventType == "" {
		eventType = ev.Type
	}

	return aggregatedEvent{
		Timestamp:   ts,
		Type:        eventType,
		Action:      action,
		ActorID:     clabutils.ShortID(short),
		ActorName:   actorName,
		ActorFullID: actorFullID,
		Attributes:  attributes,
	}
}

func ensureContainerAttributes(
	ctx context.Context,
	runtime clabruntime.ContainerRuntime,
	attributes map[string]string,
	actorFullID, actorName string,
) map[string]string {
	if runtime == nil {
		return attributes
	}

	hasIPv4 := attributes != nil && attributes["mgmt_ipv4"] != ""
	hasIPv6 := attributes != nil && attributes["mgmt_ipv6"] != ""
	hasPorts := attributes != nil && attributes["ports"] != ""

	if hasIPv4 && hasIPv6 && hasPorts {
		return attributes
	}

	filters := make([]*clabtypes.GenericFilter, 0, 2)

	if actorName == "" && attributes != nil {
		actorName = attributes["name"]
	}

	if actorName != "" {
		filters = append(filters, &clabtypes.GenericFilter{FilterType: "name", Match: actorName})
	}

	if actorFullID != "" {
		filters = append(filters, &clabtypes.GenericFilter{FilterType: "id", Match: actorFullID})
	}

	if len(filters) == 0 {
		return attributes
	}

	containers, err := runtime.ListContainers(ctx, filters)
	if err != nil {
		log.Debugf("failed to resolve container for event: %v", err)

		return attributes
	}

	container := selectContainerForEvent(containers, actorFullID, actorName)
	if container == nil {
		return attributes
	}

	if attributes == nil {
		attributes = make(map[string]string)
	}

	if !hasIPv4 {
		if ipv4 := container.GetContainerIPv4(); ipv4 != "" && ipv4 != clabconstants.NotApplicable {
			attributes["mgmt_ipv4"] = ipv4
		}
	}

	if !hasIPv6 {
		if ipv6 := container.GetContainerIPv6(); ipv6 != "" && ipv6 != clabconstants.NotApplicable {
			attributes["mgmt_ipv6"] = ipv6
		}
	}

	if !hasPorts {
		if ports := exposedPortsAttributeValue(container.Ports); ports != "" {
			attributes["ports"] = ports
		}
	}

	if len(attributes) == 0 {
		return nil
	}

	return attributes
}

func selectContainerForEvent(
	containers []clabruntime.GenericContainer,
	actorFullID, actorName string,
) *clabruntime.GenericContainer {
	if len(containers) == 0 {
		return nil
	}

	if actorFullID != "" {
		for idx := range containers {
			container := &containers[idx]

			switch {
			case container.ID == actorFullID:
				return container
			case strings.HasPrefix(container.ID, actorFullID):
				return container
			case container.ShortID == actorFullID:
				return container
			}
		}
	}

	if actorName != "" {
		for idx := range containers {
			container := &containers[idx]

			for _, name := range container.Names {
				if name == actorName {
					return container
				}
			}
		}
	}

	return &containers[0]
}

func emitContainerSnapshots(
	ctx context.Context,
	containers []clabruntime.GenericContainer,
	sink chan<- aggregatedEvent,
) {
	for idx := range containers {
		container := containers[idx]
		if !isRunningContainer(&container) && !strings.EqualFold(container.State, "exited") {
			continue
		}

		event := aggregatedEventFromContainerSnapshot(&container)
		if event.ActorID == "" && event.ActorName == "" {
			continue
		}

		select {
		case sink <- event:
		case <-ctx.Done():
			return
		}
	}
}

func aggregatedEventFromContainerSnapshot(
	container *clabruntime.GenericContainer,
) aggregatedEvent {
	if container == nil {
		return aggregatedEvent{}
	}

	state := strings.ToLower(container.State)

	short := container.ShortID
	if short == "" {
		short = clabutils.ShortID(container.ID)
	}

	attributes := cloneStringMap(container.Labels)
	if attributes == nil {
		attributes = make(map[string]string)
	}

	if _, ok := attributes["origin"]; !ok {
		attributes["origin"] = "snapshot"
	}

	if container.Image != "" {
		attributes["image"] = container.Image
	}

	if container.Status != "" {
		attributes["status"] = container.Status
	}

	if state != "" {
		attributes["state"] = state
	}

	if container.NetworkName != "" {
		attributes["network"] = container.NetworkName
	}

	if container.NetworkSettings.IPv4addr != "" {
		attributes["mgmt_ipv4"] = container.GetContainerIPv4()
	}

	if container.NetworkSettings.IPv6addr != "" {
		attributes["mgmt_ipv6"] = container.GetContainerIPv6()
	}

	if ports := exposedPortsAttributeValue(container.Ports); ports != "" {
		attributes["ports"] = ports
	}

	if len(attributes) == 0 {
		attributes = nil
	}

	actorName := firstContainerName(container)

	action := state
	if action == "" {
		action = "snapshot"
	}

	return aggregatedEvent{
		Timestamp:   time.Now(),
		Type:        "container",
		Action:      action,
		ActorID:     clabutils.ShortID(short),
		ActorName:   actorName,
		ActorFullID: container.ID,
		Attributes:  attributes,
	}
}

func cloneStringMap(input map[string]string) map[string]string {
	if len(input) == 0 {
		return nil
	}

	result := make(map[string]string, len(input))
	for k, v := range input {
		result[k] = v
	}

	return result
}

func isRunningContainer(container *clabruntime.GenericContainer) bool {
	if container == nil {
		return false
	}

	return strings.EqualFold(container.State, "running")
}

func exposedPortsAttributeValue(ports []*clabtypes.GenericPortBinding) string {
	if len(ports) == 0 {
		return ""
	}

	sortedPorts := make([]*clabtypes.GenericPortBinding, 0, len(ports))
	for idx := range ports {
		if ports[idx] != nil {
			sortedPorts = append(sortedPorts, ports[idx])
		}
	}

	if len(sortedPorts) == 0 {
		return ""
	}

	sort.Slice(sortedPorts, func(i, j int) bool {
		left := sortedPorts[i]
		right := sortedPorts[j]

		switch {
		case left.ContainerPort != right.ContainerPort:
			return left.ContainerPort < right.ContainerPort
		case left.Protocol != right.Protocol:
			return left.Protocol < right.Protocol
		case left.HostPort != right.HostPort:
			return left.HostPort < right.HostPort
		default:
			return left.HostIP < right.HostIP
		}
	})

	result := make([]string, 0, len(sortedPorts))
	for idx := range sortedPorts {
		formatted := formatExposedPort(sortedPorts[idx])
		if formatted != "" {
			result = append(result, formatted)
		}
	}

	if len(result) == 0 {
		return ""
	}

	return strings.Join(result, ";")
}

func formatExposedPort(port *clabtypes.GenericPortBinding) string {
	if port == nil {
		return ""
	}

	proto := strings.TrimSpace(strings.ToLower(port.Protocol))
	protoSuffix := ""
	if proto != "" {
		protoSuffix = "/" + proto
	}

	if port.HostPort > 0 {
		hostIP := port.HostIP
		if hostIP == "" {
			hostIP = "0.0.0.0"
		}

		if strings.Contains(hostIP, ":") {
			hostIP = fmt.Sprintf("[%s]", hostIP)
		}

		if port.ContainerPort > 0 {
			return fmt.Sprintf(
				"%s:%d%s->%d",
				hostIP,
				port.HostPort,
				protoSuffix,
				port.ContainerPort,
			)
		}

		return fmt.Sprintf("%s:%d%s", hostIP, port.HostPort, protoSuffix)
	}

	if port.ContainerPort <= 0 {
		return ""
	}

	return fmt.Sprintf("%d%s", port.ContainerPort, protoSuffix)
}

